function apiOrigin() {
  return (process.env.ALPHALAB_API_ORIGIN || 'http://127.0.0.1:8000').replace(/\/+$/, '')
}

async function run(input) {
  const params = new URLSearchParams({ profile: 'runtime' })
  for (const name of input.names || []) params.append('names', String(name))
  if (input.start) params.set('start', String(input.start))
  if (input.end) params.set('end', String(input.end))
  const response = await fetch(apiOrigin() + '/api/data/factors/returns?' + params, { headers: { Accept: 'application/json' } })
  if (!response.ok) throw new Error('AlphaLab API ' + response.status + ': ' + await response.text())
  return response.json()
}
